"""Pure filesystem checks for outputs shown as successfully generated by R39."""
from __future__ import annotations

from pathlib import Path


def _confirmed_file(path: Path) -> Path:
    candidate = Path(path).expanduser().resolve()
    if not candidate.is_file():
        raise RuntimeError(f'Expected completed output file was not found: {candidate}')
    if candidate.stat().st_size == 0:
        raise RuntimeError(f'Expected completed output file is empty: {candidate}')
    return candidate


def confirmed_model_paths(model_paths) -> tuple[str, ...]:
    """Only present models with both nonempty artifact and manifest files."""
    paths = tuple(model_paths)
    if not paths:
        raise RuntimeError('Model task did not return any output files.')
    confirmed: list[str] = []
    for item in paths:
        model = _confirmed_file(Path(item))
        manifest = _confirmed_file(Path(str(model) + '.manifest.json'))
        confirmed.extend((str(model), str(manifest)))
    return tuple(confirmed)


def confirmed_dataset_paths(folder) -> tuple[str, ...]:
    """Verify all three exported dataset files before displaying save success."""
    directory = Path(folder).expanduser().resolve()
    if not directory.is_dir():
        raise RuntimeError(f'Dataset folder was not created: {directory}')
    expected = ('preprocessed_records.csv', 'preprocessed_records.jsonl', 'preprocess_recipe.json')
    confirmed = [_confirmed_file(directory / name) for name in expected]
    return (str(directory), *(str(item) for item in confirmed))
